style.css:
@-moz-document domain("roblox.com") {
/* --- Background Image --- */
    body {
        background: url("https://i.imgur.com/u0y8CwH.jpeg") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
    }

    /* --- Pink Sidebar --- */
    .nav-container,
    #navigation,
    .left-col,
    .rbx-left-col,
    .game-home-page .menu-vertical {
        background-color: #f7c9d9 !important;
    }

    /* --- Pink Chat UI --- */
    .chat-container,
    .chat-main,
    .chat-friends-container,
    .chat-header,
    .chat-body,
    .chat-message {
        background-color: #f9d6e6 !important;
    }

    /* --- Pink Text (Roblox only) --- */
    * {
        color: #ff8ecf !important;
    }

    /* --- Make main content backgrounds transparent so background shows --- */
    .content,
    .container-main,
    .game-cards,
    .game-card-thumb-container,
    .section,
    .rbx-card {
        background: transparent !important;
    }
}
